/*
 * A067611  Numbers of the form 6xy +- x +- y, where x, y are positive
 *          integers.
 * https://oeis.org/A067611
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th positive integer k such that either 6k-1 or 6k+1
 *            is composite i.e. k is not the midpoint of a twin‑prime pair.
 *            The sequence is generated by scanning natural numbers and
 *            storing the first n that satisfy the condition
 * Range:     u8 n <= 206, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   mul_mod64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/mul_mod64.h"

/*-------------------------------------------------------------*/
/*  64‑bit deterministic Miller–Rabin primality test           */
/*-------------------------------------------------------------*/

static uint64_t pow_mod64(uint64_t base, uint64_t exp, uint64_t mod)
{
    uint64_t res = 1;
    uint64_t b   = base % mod;
    while (exp) {
        if (exp & 1U) res = mul_mod64(res, b, mod);
        b = mul_mod64(b, b, mod);
        exp >>= 1U;
    }
    return res;
}

static bool isPrime64(uint64_t n)
{
    if (n < 2) return false;

    /* small primes check */
    static const uint64_t small_primes[] = {
        2ULL,3ULL,5ULL,7ULL,11ULL,13ULL,17ULL,19ULL,23ULL,29ULL,31ULL,37ULL
    };
    for (size_t i = 0; i < sizeof(small_primes) / sizeof(small_primes[0]); ++i) {
        uint64_t p = small_primes[i];
        if (n == p) return true;
        if (n % p == 0) return false;
    }

    /* write n-1 = d * 2^s */
    uint64_t d = n - 1;
    unsigned s = 0;
    while ((d & 1ULL) == 0ULL) {
        d >>= 1ULL;
        ++s;
    }

    /* bases that give deterministic test for 64-bit n */
    static const uint64_t bases[] = {
        2ULL, 325ULL, 9375ULL, 28178ULL, 450775ULL, 9780504ULL, 1795265022ULL
    };
    for (size_t i = 0; i < sizeof(bases) / sizeof(bases[0]); ++i) {
        uint64_t a = bases[i] % n;
        if (!a) continue;
        uint64_t x = pow_mod64(a, d, n);
        if (x == 1ULL || x == n - 1) continue;
        bool composite = true;
        for (unsigned r = 1; r < s; ++r) {
            x = mul_mod64(x, x, n);
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite) return false;
    }
    return true;
}

/*-------------------------------------------------------------*/
/*  Sequence A067611                                          */
/*-------------------------------------------------------------*/
seq_t a(idx_t n)
{
    /* static cache of found terms                   */
    static seq_t *terms   = NULL;
    static size_t terms_len = 0;
    static size_t terms_cap = 0;
    static idx_t next_to_test = 1;   /* next natural number k to test */

    /* generate terms until we have at least n terms   */
    while (terms_len < n) {
        idx_t k = next_to_test++;

        uint64_t p1 = 6ULL * k - 1;
        uint64_t p2 = 6ULL * k + 1;
        bool is_p1 = isPrime64(p1);
        bool is_p2 = isPrime64(p2);

        /* k is added if it is NOT a twin‑prime midpoint             */
        if (!(is_p1 && is_p2)) {
            if (terms_len == terms_cap) {
                size_t new_cap = terms_cap ? (terms_cap << 1) : 16;
                seq_t *tmp = (seq_t *)realloc(terms, new_cap * sizeof(seq_t));
                if (!tmp) {
                    free(terms);
                    exit(1);
                }
                terms = tmp;
                terms_cap = new_cap;
            }
            terms[terms_len++] = (seq_t)k;
        }
    }
    return terms[n - 1];
}
